import { Recipe, Shell } from '../util/index.ts'

export type Shared = { cwd: string }
export type CommitOptions = { message: string; amend: boolean; no_edit: boolean }

const git = <T extends Record<string, any>>(params: string[], options: T) =>
  Recipe.create<T & Shared, string>({ ...options, cwd: process.cwd() }, ({ cwd, ...o }) =>
    Shell.sh('git', [...params, ...toArgs(o)], { cwd }).then((r) => r.stdout),
  )

const toArgs = <T extends Record<string, any>>(x: T): string[] => {
  const args = []
  for (const [key, value] of Object.entries(x)) {
    if (value === undefined) continue
    if (typeof value === 'boolean') {
      if (value) args.push(`--${getKey(key)}`)
      continue
    }
    args.push(`--${getKey(key)}`, value)
  }
  return args
}

const getKey = (key: string) => key.replace(/_/g, '-')

export const commit = git<CommitOptions>(['commit'], { message: '', amend: true, no_edit: true })

export type TagOptions = { name: string }
export const tag = git<TagOptions>(['tag'], { name: '' })

export type PushOptions = { force: boolean }
export const push = git<PushOptions>(['push'], { force: true })
